create schema if not exists realtime;

create table if not exists realtime.members (
  resource text not null,
  channel_key text not null,
  user_id text not null,
  primary key (resource, channel_key, user_id)
);

create index if not exists members_by_user on realtime.members (user_id, resource);

create or replace function realtime.listed_members(entry jsonb, members_column text, deleted_column text) returns setof text
language sql immutable as $$
  select distinct member from jsonb_array_elements_text(
    case when (deleted_column = '' or entry ->> deleted_column is null) and jsonb_typeof(entry -> members_column) = 'array' then entry -> members_column else '[]'::jsonb end
  ) as member where member is not null
$$;

create or replace function realtime.members_kept() returns trigger
language plpgsql as $$
declare
  channel_resource text := tg_argv[0];
  key_column text := tg_argv[1];
  members_column text := tg_argv[2];
  deleted_column text := tg_argv[3];
  old_entry jsonb;
  new_entry jsonb;
begin
  if tg_op = 'TRUNCATE' then
    delete from realtime.members m where m.resource = channel_resource;
    return null;
  end if;
  if tg_op <> 'INSERT' then old_entry := to_jsonb(old); end if;
  if tg_op <> 'DELETE' then new_entry := to_jsonb(new); end if;
  delete from realtime.members m where m.resource = channel_resource and m.channel_key = old_entry ->> key_column
    and (new_entry is null or m.channel_key is distinct from new_entry ->> key_column
      or m.user_id not in (select realtime.listed_members(new_entry, members_column, deleted_column)));
  if new_entry is not null then
    insert into realtime.members (resource, channel_key, user_id)
      select channel_resource, new_entry ->> key_column, member from realtime.listed_members(new_entry, members_column, deleted_column) as member
      on conflict do nothing;
  end if;
  return null;
end
$$;

comment on function realtime.members_kept() is 'Protobase realtime members 1';

create trigger realtime_members after insert or delete or update of "id", "members", "deleted_at" on "directs" for each row execute function realtime.members_kept('directs', 'id', 'members', 'deleted_at');

create trigger realtime_members_truncated after truncate on "directs" for each statement execute function realtime.members_kept('directs');

delete from realtime.members where resource = 'directs';

insert into realtime.members (resource, channel_key, user_id)
  select 'directs', to_jsonb(t) ->> 'id', member from "directs" t
  cross join lateral realtime.listed_members(to_jsonb(t), 'members', 'deleted_at') as member
  on conflict do nothing;

delete from realtime.members where resource <> all(array['directs']::text[]);
